import { lstatSync as nodeLstatSync, readdirSync, statSync as nodeStatSync } from "node:fs";
import type { Stats } from "node:fs";
import { lstat as nodeLstat, opendir, stat as nodeStat } from "node:fs/promises";

export interface DirEntry {
  name: string;
  isFile: boolean;
  isDirectory: boolean;
  isSymlink: boolean;
}

export interface FileInfo {
  isFile: boolean;
  isDirectory: boolean;
  isSymlink: boolean;
  size: number;
  mtime: Date | null;
  atime: Date | null;
  birthtime: Date | null;
  ctime: Date | null;
  dev: number;
  ino: number | null;
  mode: number | null;
  nlink: number | null;
  uid: number | null;
  gid: number | null;
  rdev: number | null;
  blksize: number | null;
  blocks: number | null;
  isBlockDevice: boolean | null;
  isCharDevice: boolean | null;
  isFifo: boolean | null;
  isSocket: boolean | null;
}

type PathLike = string | URL;

export async function* readDir(path: PathLike): AsyncIterableIterator<DirEntry> {
  const dir = await opendir(path);
  for await (const entry of dir) {
    yield {
      name: entry.name,
      isFile: entry.isFile(),
      isDirectory: entry.isDirectory(),
      isSymlink: entry.isSymbolicLink(),
    };
  }
}

export function readDirSync(path: PathLike): DirEntry[] {
  return readdirSync(path, { withFileTypes: true }).map((entry) => ({
    name: entry.name,
    isFile: entry.isFile(),
    isDirectory: entry.isDirectory(),
    isSymlink: entry.isSymbolicLink(),
  }));
}

function toFileInfo(stats: Stats): FileInfo {
  const windows = process.platform === "win32";
  const unixOnly = <T>(value: T): T | null => (windows ? null : value);
  return {
    isFile: stats.isFile(),
    isDirectory: stats.isDirectory(),
    isSymlink: stats.isSymbolicLink(),
    size: stats.size,
    mtime: stats.mtime,
    atime: stats.atime,
    birthtime: stats.birthtime,
    ctime: stats.ctime,
    dev: stats.dev,
    ino: unixOnly(stats.ino),
    mode: unixOnly(stats.mode),
    nlink: unixOnly(stats.nlink),
    uid: unixOnly(stats.uid),
    gid: unixOnly(stats.gid),
    rdev: unixOnly(stats.rdev),
    blksize: unixOnly(stats.blksize),
    blocks: unixOnly(stats.blocks),
    isBlockDevice: unixOnly(stats.isBlockDevice()),
    isCharDevice: unixOnly(stats.isCharacterDevice()),
    isFifo: unixOnly(stats.isFIFO()),
    isSocket: unixOnly(stats.isSocket()),
  };
}

export async function stat(path: PathLike): Promise<FileInfo> {
  return toFileInfo(await nodeStat(path));
}

export async function lstat(path: PathLike): Promise<FileInfo> {
  return toFileInfo(await nodeLstat(path));
}

export function statSync(path: PathLike): FileInfo {
  return toFileInfo(nodeStatSync(path));
}

export function lstatSync(path: PathLike): FileInfo {
  return toFileInfo(nodeLstatSync(path));
}
